--
-- 表的结构 `adminSessions`
--

CREATE TABLE `adminSessions` (
                                 `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话ID',
                                 `userId` bigint(20) UNSIGNED DEFAULT NULL COMMENT '用户ID',
                                 `ipAddress` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IP地址',
                                 `userAgent` text COLLATE utf8mb4_unicode_ci COMMENT '用户代理',
                                 `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话数据',
                                 `lastActivity` int(11) NOT NULL COMMENT '最后活动时间（时间戳）',
                                 `rememberToken` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '记住我令牌',
                                 `expiresAt` datetime DEFAULT NULL COMMENT '过期时间',
                                 `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='管理员会话表';

