--
-- 表的结构 `adminSystemSettings`
--

CREATE TABLE `adminSystemSettings` (
                                       `id` int(11) NOT NULL COMMENT '设置ID',
                                       `settingKey` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设置键',
                                       `settingValue` text COLLATE utf8mb4_unicode_ci COMMENT '设置值',
                                       `settingType` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'string' COMMENT '值类型（string, number, boolean, json）',
                                       `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设置分类（login, security, email, general等）',
                                       `displayName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显示名称',
                                       `description` text COLLATE utf8mb4_unicode_ci COMMENT '设置描述',
                                       `isPublic` tinyint(1) DEFAULT '0' COMMENT '是否公开（客户端可见）',
                                       `isEditable` tinyint(1) DEFAULT '1' COMMENT '是否可编辑',
                                       `sortOrder` int(11) DEFAULT '0' COMMENT '排序',
                                       `updatedBy` bigint(20) UNSIGNED DEFAULT NULL COMMENT '更新人ID',
                                       `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                       `updatedAt` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统设置表';

