--
-- 表的结构 `adminUsers`
--

CREATE TABLE `adminUsers` (
                              `id` bigint(20) UNSIGNED NOT NULL COMMENT '用户ID',
                              `username` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户名（用于登录）',
                              `email` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '邮箱地址',
                              `passwordHash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码哈希值',
                              `fullName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '全名',
                              `avatarInitials` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '头像缩写（如 JD, SM）',
                              `avatarColor` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '头像背景色（CSS gradient）',
                              `roleId` int(11) NOT NULL COMMENT '角色ID（外键）',
                              `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci DEFAULT 'active' COMMENT '账户状态',
                              `isLocked` tinyint(1) DEFAULT '0' COMMENT '账户是否锁定',
                              `failedLoginAttempts` int(11) DEFAULT '0' COMMENT '失败登录次数',
                              `lastLoginAt` datetime DEFAULT NULL COMMENT '最后登录时间',
                              `lastLoginIp` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后登录IP',
                              `rememberToken` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '记住我令牌',
                              `passwordChangedAt` datetime DEFAULT NULL COMMENT '密码最后修改时间',
                              `mustChangePassword` tinyint(1) DEFAULT '0' COMMENT '是否必须修改密码',
                              `twoFactorEnabled` tinyint(1) DEFAULT '0' COMMENT '是否启用双因素认证',
                              `twoFactorSecret` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '双因素认证密钥',
                              `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
