--
-- 表的结构 `autoApprovalLog`
--

CREATE TABLE `autoApprovalLog` (
                                   `id` bigint(20) UNSIGNED NOT NULL,
                                   `transactionType` enum('deposit','withdrawal') COLLATE utf8mb4_unicode_ci NOT NULL,
                                   `transactionId` bigint(20) UNSIGNED NOT NULL COMMENT 'ID from deposits or withdrawals table',
                                   `transactionRefId` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Transaction reference ID (TXN-YYYYMMDD-XXXXX)',
                                   `userId` bigint(20) UNSIGNED NOT NULL COMMENT 'Client user ID',
                                   `ruleId` int(11) UNSIGNED DEFAULT NULL COMMENT 'Auto-approval rule that was applied (NULL if rejected)',
                                   `wasAutoApproved` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Whether transaction was auto-approved',
                                   `checkResults` text COLLATE utf8mb4_unicode_ci COMMENT 'JSON object with detailed check results',
                                   `rejectionReason` text COLLATE utf8mb4_unicode_ci COMMENT 'Reason why auto-approval was not granted',
                                   `amount` decimal(15,2) NOT NULL COMMENT 'Transaction amount',
                                   `clientCountry` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client country code at time of transaction',
                                   `clientTags` text COLLATE utf8mb4_unicode_ci COMMENT 'Client tags at time of transaction',
                                   `kycStatus` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client KYC status at time of transaction',
                                   `checkedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                   `ipAddress` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IP address of transaction request'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Auto-approval decision audit log';

