--
-- 表的结构 `clientEmailTemplates`
--

CREATE TABLE `clientEmailTemplates` (
                                        `id` bigint(20) UNSIGNED NOT NULL,
                                        `templateKey` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
                                        `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
                                        `subject` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
                                        `body` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
                                        `isActive` tinyint(1) NOT NULL DEFAULT '1',
                                        `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                        `updatedAt` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- 插入之前先把表清空（truncate） `clientEmailTemplates`
--

TRUNCATE TABLE `clientEmailTemplates`;
--
-- 转存表中的数据 `clientEmailTemplates`
--

INSERT INTO `clientEmailTemplates` (`id`, `templateKey`, `name`, `subject`, `body`, `isActive`, `createdAt`, `updatedAt`) VALUES
                                                                                                                              (1, 'welcome', 'Welcome Email', 'Welcome to Utrada CRM', '<p>Dear {{firstName}} {{lastName}},</p>\r\n      <p>Welcome to Utrada CRM! We are excited to help you manage your trading journey. If you have any questions, feel free to reach out to our support team.</p>\r\n      <p>Best regards,<br>Utrada CRM Team</p>', 1, '2025-11-11 11:41:26', NULL),
                                                                                                                              (2, 'deposit_confirmation', 'Deposit Confirmation', 'Your Deposit Has Been Received', '<p>Hello {{firstName}},</p>\r\n      <p>We have successfully received your deposit of <strong>{{amount}}</strong> on {{date}}. The funds are now available in your account.</p>\r\n      <p>If you have any questions, please contact your account manager.</p>\r\n      <p>Regards,<br>Utrada CRM Team</p>', 1, '2025-11-11 11:41:26', NULL),
                                                                                                                              (3, 'withdrawal_update', 'Withdrawal Update', 'Withdrawal Request Update', '<p>Hi {{firstName}},</p>\r\n      <p>Your withdrawal request submitted on {{date}} is currently <strong>{{status}}</strong>. We will notify you once the transfer is completed.</p>\r\n      <p>Thank you for choosing Utrada CRM.</p>\r\n      <p>Sincerely,<br>Utrada CRM Team</p>', 1, '2025-11-11 11:41:26', NULL),
                                                                                                                              (4, 'kyc_reminder', 'KYC Reminder', 'Reminder: Complete Your KYC Verification', '<p>Dear {{firstName}},</p>\r\n      <p>This is a friendly reminder to complete your KYC verification. Please log in to your portal and upload the required documents as soon as possible.</p>\r\n      <p>If you need assistance, contact our compliance team.</p>\r\n      <p>Best regards,<br>Utrada CRM Team</p>', 1, '2025-11-11 11:41:26', NULL),
                                                                                                                              (5, 'promotion', 'Promotional Offer', 'Exclusive Trading Promotion Just for You', '<p>Hello {{firstName}},</p>\r\n      <p>We are excited to share an exclusive promotion tailored for you. Enjoy <strong>{{promotionDetails}}</strong> when you trade between {{startDate}} and {{endDate}}.</p>\r\n      <p>Don’t miss out on this opportunity!</p>\r\n      <p>Warm regards,<br>Utrada CRM Team</p>', 1, '2025-11-11 11:41:26', NULL);

