                                 `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ticket title/subject',
                                 `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ticket content/message',
