--
-- 表的结构 `clientUsers`
--

CREATE TABLE `clientUsers` (
                               `id` int(11) UNSIGNED NOT NULL,
                               `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
                               `passwordHash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
                               `firstName` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                               `lastName` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                               `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                               `phoneCountryCode` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Phone country code (e.g., +1, +44, +86)',
                               `country` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                               `emailVerified` tinyint(1) NOT NULL DEFAULT '0',
                               `emailVerifiedAt` datetime DEFAULT NULL,
                               `status` enum('active','inactive','suspended','pending_verification') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending_verification',
                               `registrationIp` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                               `lastLoginAt` datetime DEFAULT NULL,
                               `lastLoginIp` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                               `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
                               `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                               `kycStatus` enum('not_started','in_progress','submitted','under_review','approved','rejected','incomplete') COLLATE utf8mb4_unicode_ci DEFAULT 'not_started' COMMENT 'KYC verification status',
                               `kycSubmissionId` int(11) UNSIGNED DEFAULT NULL COMMENT 'Latest KYC submission ID',
                               `verifiedAt` datetime DEFAULT NULL COMMENT 'KYC verification completion date',
                               `tags` text COLLATE utf8mb4_unicode_ci COMMENT 'Client tags (JSON format)',
                               `assignedTo` int(11) UNSIGNED DEFAULT NULL COMMENT 'Assigned admin user ID',
                               `accountManagerId` bigint(20) UNSIGNED DEFAULT NULL,
                               `accountManagerAssignedAt` datetime DEFAULT NULL,
                               `accountManagerNote` text COLLATE utf8mb4_unicode_ci,
                               `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Admin notes about the client'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Client user accounts';

