--
-- 表的结构 `deposits`
--

CREATE TABLE `deposits` (
                            `id` bigint(20) UNSIGNED NOT NULL,
                            `transactionId` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Unique transaction ID (TXN-YYYYMMDD-XXXXX)',
                            `userId` int(11) UNSIGNED NOT NULL COMMENT 'Client user ID',
                            `tradingAccountId` int(11) UNSIGNED DEFAULT NULL COMMENT 'Target trading account',
                            `paymentMethodId` int(11) UNSIGNED NOT NULL,
                            `amount` decimal(15,2) NOT NULL COMMENT 'Deposit amount in USD',
                            `amountCrypto` decimal(20,8) DEFAULT NULL COMMENT 'Amount in cryptocurrency if applicable',
                            `cryptoNetwork` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'erc20, trc20, bep20, mainnet',
                            `fromAddress` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sender wallet address or bank account',
                            `toAddress` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Our receiving wallet address',
                            `networkFee` decimal(15,2) DEFAULT '0.00' COMMENT 'Network/transaction fee',
                            `platformFee` decimal(15,2) DEFAULT '0.00' COMMENT 'Platform service fee',
                            `netAmount` decimal(15,2) NOT NULL COMMENT 'Net amount credited to client',
                            `exchangeRate` decimal(20,8) DEFAULT NULL COMMENT 'Crypto to USD exchange rate at time of deposit',
                            `status` enum('pending','processing','completed','failed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
                            `confirmations` int(11) DEFAULT '0' COMMENT 'Current blockchain confirmations',
                            `requiredConfirmations` int(11) DEFAULT '3' COMMENT 'Required confirmations',
                            `transactionHash` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Blockchain transaction hash',
                            `gatewayTransactionId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'External gateway transaction ID',
                            `gatewayResponse` text COLLATE utf8mb4_unicode_ci COMMENT 'JSON response from payment gateway',
                            `requestedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'When client initiated deposit',
                            `approvedAt` datetime DEFAULT NULL COMMENT 'When admin approved',
                            `approvedBy` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Admin user ID',
                            `completedAt` datetime DEFAULT NULL COMMENT 'When deposit was completed',
                            `failureReason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
                            `adminNotes` text COLLATE utf8mb4_unicode_ci COMMENT 'Internal admin notes',
                            `clientNotes` text COLLATE utf8mb4_unicode_ci COMMENT 'Notes from client',
                            `ipAddress` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client IP when requesting',
                            `userAgent` text COLLATE utf8mb4_unicode_ci,
                            `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
                            `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Client deposit transactions';

