--
-- 表的结构 `emailTemplates`
--

CREATE TABLE `emailTemplates` (
                                  `id` int(11) NOT NULL,
                                  `templateKey` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '唯一标识符，用于代码中引用',
                                  `templateName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
                                  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'general' COMMENT '模板分类：registration, kyc, transaction, account, notification, etc.',
                                  `emailSubject` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '邮件主题（支持变量替换）',
                                  `emailBody` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '邮件内容（HTML格式，支持变量替换）',
                                  `recipientType` enum('client','admin','both') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'client' COMMENT '收件人类型：client=客户端用户, admin=后台管理员, both=两者',
                                  `description` text COLLATE utf8mb4_unicode_ci COMMENT '模板描述',
                                  `variables` text COLLATE utf8mb4_unicode_ci COMMENT '可用变量说明（JSON格式）',
                                  `isActive` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用',
                                  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='邮件模板管理表';

--
-- 插入之前先把表清空（truncate） `emailTemplates`
--

TRUNCATE TABLE `emailTemplates`;
--
-- 转存表中的数据 `emailTemplates`
--

INSERT INTO `emailTemplates` (`id`, `templateKey`, `templateName`, `category`, `emailSubject`, `emailBody`, `recipientType`, `description`, `variables`, `isActive`, `createdAt`, `updatedAt`) VALUES
                                                                                                                                                                                                   (1, 'ib_invitation', 'IB Invitation Email', 'notification', 'Invitation to Become an Introducing Broker (IB) - {{invitationCode}}', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <style>\r\n        body {\r\n            font-family: Arial, sans-serif;\r\n            line-height: 1.6;\r\n            color: #333;\r\n            max-width: 600px;\r\n            margin: 0 auto;\r\n            padding: 20px;\r\n        }\r\n        .header {\r\n            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\r\n            color: white;\r\n            padding: 30px 20px;\r\n            text-align: center;\r\n            border-radius: 8px 8px 0 0;\r\n        }\r\n        .content {\r\n            background: #f7fafc;\r\n            padding: 30px 20px;\r\n            border: 1px solid #e2e8f0;\r\n        }\r\n        .invitation-code {\r\n            background: white;\r\n            border: 2px dashed #667eea;\r\n            padding: 15px;\r\n            text-align: center;\r\n            margin: 20px 0;\r\n            border-radius: 6px;\r\n        }\r\n        .invitation-code strong {\r\n            font-size: 18px;\r\n            color: #667eea;\r\n            letter-spacing: 2px;\r\n        }\r\n        .button {\r\n            display: inline-block;\r\n            background: #667eea;\r\n            color: white;\r\n            padding: 12px 30px;\r\n            text-decoration: none;\r\n            border-radius: 6px;\r\n            margin: 20px 0;\r\n            font-weight: 600;\r\n        }\r\n        .button:hover {\r\n            background: #5568d3;\r\n        }\r\n        .documents-list {\r\n            background: white;\r\n            padding: 15px;\r\n            margin: 15px 0;\r\n            border-radius: 6px;\r\n            border-left: 4px solid #667eea;\r\n        }\r\n        .documents-list ul {\r\n            margin: 10px 0;\r\n            padding-left: 20px;\r\n        }\r\n        .documents-list li {\r\n            margin: 8px 0;\r\n        }\r\n        .footer {\r\n            text-align: center;\r\n            color: #718096;\r\n            font-size: 12px;\r\n            padding: 20px;\r\n            border-top: 1px solid #e2e8f0;\r\n        }\r\n        .warning {\r\n            background: #fff3cd;\r\n            border: 1px solid #ffc107;\r\n            padding: 15px;\r\n            border-radius: 6px;\r\n            margin: 15px 0;\r\n        }\r\n        .warning strong {\r\n            color: #856404;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"header\">\r\n        <h1>IB Partnership Invitation</h1>\r\n    </div>\r\n    <div class=\"content\">\r\n        <p>Dear {{clientName}},</p>\r\n\r\n        <p>We are pleased to invite you to become an Introducing Broker (IB) partner with our platform. As an IB, you will have the opportunity to:</p>\r\n\r\n        <ul>\r\n            <li>Earn competitive commissions from client referrals</li>\r\n            <li>Access advanced IB management tools and reporting</li>\r\n            <li>Build your own network of trading clients</li>\r\n            <li>Receive dedicated support from our IB team</li>\r\n        </ul>\r\n\r\n        <div class=\"invitation-code\">\r\n            <strong>Your Invitation Code: {{invitationCode}}</strong>\r\n        </div>\r\n\r\n        {{customMessageSection}}\r\n\r\n        {{documentsSection}}\r\n\r\n        <div class=\"warning\">\r\n            <strong>⚠️ Important:</strong>\r\n            <p style=\"margin: 10px 0 0 0;\">\r\n                This invitation will expire on <strong>{{expiryDate}}</strong>.\r\n                Please accept or decline the invitation before the expiration date.\r\n            </p>\r\n        </div>\r\n\r\n        <p style=\"text-align: center; margin: 30px 0;\">\r\n            <a href=\"{{acceptLink}}\" class=\"button\">Accept Invitation</a>\r\n        </p>\r\n\r\n        <p style=\"font-size: 13px; color: #718096; text-align: center;\">\r\n            Or copy and paste this link into your browser:<br>\r\n            <a href=\"{{acceptLink}}\" style=\"color: #667eea; word-break: break-all;\">{{acceptLink}}</a>\r\n        </p>\r\n\r\n        <p>If you have any questions about this invitation or the IB program, please do not hesitate to contact our support team.</p>\r\n\r\n        <p>Best regards,<br>\r\n        <strong>{{invitedByName}}</strong><br>\r\n        IB Partnership Team</p>\r\n    </div>\r\n    <div class=\"footer\">\r\n        <p>This is an automated email. Please do not reply to this message.</p>\r\n        <p>&copy; {{currentYear}} {{platformName}}. All rights reserved.</p>\r\n    </div>\r\n</body>\r\n</html>', 'client', 'Email template for sending IB partnership invitations to clients. This template includes invitation code, document requirements, and acceptance link.', '{\r\n        \"clientName\": \"Client full name\",\r\n        \"invitationCode\": \"Unique invitation code (e.g., IB-INV-XXXXXX)\",\r\n        \"customMessage\": \"Optional custom message from admin\",\r\n        \"documents\": \"Array of document titles that need to be reviewed\",\r\n        \"expiryDate\": \"Invitation expiration date (formatted)\",\r\n        \"acceptLink\": \"Full URL to accept the invitation\",\r\n        \"invitedByName\": \"Name of admin who sent the invitation\",\r\n        \"currentYear\": \"Current year\",\r\n        \"platformName\": \"Platform/company name\"\r\n    }', 1, '2025-12-09 08:51:30', '2025-12-09 08:51:30'),
                                                                                                                                                                                                   (2, 'ib_application_approved', 'IB Application Approved Notification', 'notification', 'Congratulations! Your IB Partnership Application Has Been Approved', '<p>Dear {{applicantName}},</p>\r\n\r\n             <p>We are pleased to inform you that your IB (Introducing Broker) partnership application has been <strong>approved</strong>!</p>\r\n\r\n             <p><strong>Application Details:</strong></p>\r\n             <ul>\r\n               <li>Application ID: {{applicationId}}</li>\r\n               <li>IB Code: {{ibCode}}</li>\r\n               <li>Tier Level: {{tierLevel}}</li>\r\n               <li>Approval Date: {{approvalDate}}</li>\r\n             </ul>\r\n\r\n             <p><strong>Next Steps:</strong></p>\r\n             <ul>\r\n               <li>You can now start referring clients and earning commissions</li>\r\n               <li>Access your IB portal to track your referrals and commissions</li>\r\n               <li>Review your assigned commission rules and tier benefits</li>\r\n             </ul>\r\n\r\n             <p>If you have any questions or need assistance, please contact our support team.</p>\r\n\r\n             <p>Welcome to our IB partner network!</p>\r\n\r\n             <p>Best regards,<br>\r\n             {{teamName}}</p>', 'client', 'Email notification sent to client when IB application is approved', '{\"applicantName\": \"Applicant name\", \"applicationId\": \"Application ID\", \"ibCode\": \"IB Partner Code\", \"tierLevel\": \"Assigned Tier Level\", \"approvalDate\": \"Approval date and time\"}', 1, '2025-12-23 02:29:14', '2025-12-23 02:29:14'),
                                                                                                                                                                                                   (3, 'email_verification_code', 'Email Verification Code', 'notification', 'Email Verification Code', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <style>\r\n        body {\r\n            font-family: Arial, sans-serif;\r\n            line-height: 1.6;\r\n            color: #333;\r\n            max-width: 600px;\r\n            margin: 0 auto;\r\n            padding: 20px;\r\n        }\r\n        .container {\r\n            max-width: 600px;\r\n            margin: 0 auto;\r\n            padding: 20px;\r\n        }\r\n        .header {\r\n            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\r\n            color: white;\r\n            padding: 30px;\r\n            text-align: center;\r\n            border-radius: 8px 8px 0 0;\r\n        }\r\n        .content {\r\n            background: #f7fafc;\r\n            padding: 30px;\r\n            border-radius: 0 0 8px 8px;\r\n        }\r\n        .otp-box {\r\n            background: white;\r\n            border: 3px solid #667eea;\r\n            border-radius: 8px;\r\n            padding: 20px;\r\n            text-align: center;\r\n            margin: 20px 0;\r\n        }\r\n        .otp-code {\r\n            font-size: 32px;\r\n            font-weight: bold;\r\n            color: #667eea;\r\n            letter-spacing: 8px;\r\n            margin: 10px 0;\r\n        }\r\n        .warning {\r\n            background: #fff5f5;\r\n            border-left: 4px solid #fc8181;\r\n            padding: 15px;\r\n            margin: 20px 0;\r\n            border-radius: 4px;\r\n        }\r\n        .footer {\r\n            text-align: center;\r\n            color: #718096;\r\n            font-size: 12px;\r\n            margin-top: 20px;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"header\">\r\n            <h1>📧 Email Verification</h1>\r\n        </div>\r\n        <div class=\"content\">\r\n            <p>Hello {{userName}},</p>\r\n            <p>You have requested to change your email address. Please use the verification code below:</p>\r\n\r\n            <div class=\"otp-box\">\r\n                <p style=\"margin: 0; color: #718096; font-size: 14px;\">Your Verification Code</p>\r\n                <div class=\"otp-code\">{{otpCode}}</div>\r\n                <p style=\"margin: 0; color: #718096; font-size: 13px;\">Valid for {{validityMinutes}} minutes</p>\r\n            </div>\r\n\r\n            <div class=\"warning\">\r\n                <p style=\"margin: 0;\"><strong>⚠️ Security Notice:</strong></p>\r\n                <p style=\"margin: 5px 0 0 0;\">Never share this code with anyone. Our team will never ask for your verification code.</p>\r\n            </div>\r\n\r\n            <p>If you did not request this change, please contact our support team immediately and change your account password.</p>\r\n\r\n            <div class=\"footer\">\r\n                <p>This is an automated message, please do not reply to this email.</p>\r\n                <p>&copy; {{currentYear}} {{platformName}}. All rights reserved.</p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>', 'both', 'Email template for sending email verification codes to users (both admin and client) when changing email address.', '{\r\n        \"userName\": \"User full name or username\",\r\n        \"otpCode\": \"6-digit verification code\",\r\n        \"validityMinutes\": \"Validity period in minutes (e.g., 10)\",\r\n        \"platformName\": \"Platform/company name\",\r\n        \"currentYear\": \"Current year\"\r\n    }', 1, '2025-12-23 02:32:50', '2025-12-23 02:32:50'),
                                                                                                                                                                                                   (4, 'kyc_submission_confirmation', 'KYC Submission Confirmation', 'kyc', 'Your KYC Verification Has Been Submitted', '<p>Dear {{clientName}},</p><p>Thank you for submitting your KYC verification documents. We have received your application and our compliance team will review it shortly.</p><p><strong>What happens next?</strong></p><ul><li>Our team will verify your documents within 1-2 business days</li><li>You will receive an email notification once the review is complete</li><li>You can track your verification status in your dashboard</li></ul><p>If you have any questions, please don\'t hesitate to contact our support team.</p><p>Best regards,<br>{{platformName}} Team</p>', 'client', 'Email notification sent to client when KYC submission is confirmed', '{\"clientName\": \"Client full name\", \"platformName\": \"Platform/company name\"}', 1, '2025-12-23 02:33:03', '2025-12-23 02:33:03'),
(5, 'kyc_approval_notification', 'KYC Approval Notification', 'kyc', 'Your KYC Verification Has Been Approved!', '<p>Dear {{clientName}},</p><p>Great news! Your KYC verification has been approved.</p><p><strong>What this means for you:</strong></p><ul><li>Full access to all trading features</li><li>Higher transaction limits</li><li>Priority customer support</li><li>Access to advanced trading tools</li></ul><p>You can now start trading with complete confidence.</p><p><a href=\"{{dashboardUrl}}\">Go to Dashboard</a></p><p>Best regards,<br>{{platformName}} Team</p>', 'client', 'Email notification sent to client when KYC verification is approved', '{\"clientName\": \"Client full name\", \"dashboardUrl\": \"Dashboard URL link\", \"platformName\": \"Platform/company name\"}', 1, '2025-12-23 02:33:03', '2025-12-23 02:33:03'),
(6, 'kyc_rejection_notification', 'KYC Rejection Notification', 'kyc', 'Action Required: KYC Verification Issue', '<p>Dear {{clientName}},</p><p>We regret to inform you that we were unable to approve your KYC verification at this time.</p><p><strong>Reason for rejection:</strong></p><p>{{rejectionReason}}</p><p><strong>Next steps:</strong></p><ul><li>Review the feedback provided</li><li>Prepare the required documents</li><li>Resubmit your KYC application</li></ul><p><a href=\"{{resubmitUrl}}\">Resubmit Documents</a></p><p>If you need assistance, our support team is here to help.</p><p>Best regards,<br>{{platformName}} Team</p>', 'client', 'Email notification sent to client when KYC verification is rejected', '{\"clientName\": \"Client full name\", \"rejectionReason\": \"Reason for rejection\", \"resubmitUrl\": \"Resubmit documents URL\", \"platformName\": \"Platform/company name\"}', 1, '2025-12-23 02:33:03', '2025-12-23 02:33:03'),
(7, 'kyc_under_review_notification', 'KYC Under Review', 'kyc', 'Your KYC Verification Is Under Review', '<p>Dear {{clientName}},</p><p>Your KYC documents are currently being reviewed by our compliance team.</p><p><strong>Review timeline:</strong></p><ul><li>Standard review: 1-2 business days</li><li>Complex cases: up to 5 business days</li><li>You will be notified as soon as the review is complete</li></ul><p>You can track your verification status in your dashboard.</p><p><a href=\"{{statusUrl}}\">Check Status</a></p><p>Thank you for your patience.</p><p>Best regards,<br>{{platformName}} Team</p>', 'client', 'Email notification sent to client when KYC verification is under review', '{\"clientName\": \"Client full name\", \"statusUrl\": \"KYC status check URL\", \"platformName\": \"Platform/company name\"}', 1, '2025-12-23 02:33:03', '2025-12-23 02:33:03'),
(8, 'kyc_expiry_reminder', 'KYC Expiry Reminder', 'kyc', 'Your KYC Verification Will Expire Soon', '<p>Dear {{clientName}},</p><p>This is a friendly reminder that your KYC verification will expire on <strong>{{expiryDate}}</strong>.</p><p><strong>To maintain uninterrupted access:</strong></p><ul><li>Update your documents before the expiry date</li><li>Ensure all information is current and accurate</li><li>Submit updated proof of address if required</li></ul><p><a href=\"{{updateUrl}}\">Update Documents</a></p><p>Best regards,<br>{{platformName}} Team</p>', 'client', 'Email reminder sent to client when KYC verification is about to expire', '{\"clientName\": \"Client full name\", \"expiryDate\": \"Expiry date (formatted)\", \"updateUrl\": \"Update documents URL\", \"platformName\": \"Platform/company name\"}', 1, '2025-12-23 02:33:03', '2025-12-23 02:33:03'),
(9, 'kyc_resubmit_request', 'KYC Resubmission Required', 'kyc', 'Additional Information Required for KYC Verification', '<p>Dear {{clientName}},</p><p>We need additional information to complete your KYC verification.</p><p><strong>Required items:</strong></p><p>{{requiredItems}}</p><p><strong>Please note:</strong></p><ul><li>Submit the requested documents within 7 days</li><li>Ensure all documents are clear and legible</li><li>Documents must be recent and valid</li></ul><p><a href=\"{{resubmitUrl}}\">Submit Documents</a></p><p>If you have questions, please contact our support team.</p><p>Best regards,<br>{{platformName}} Team</p>', 'client', 'Email notification sent to client when additional KYC information is required', '{\"clientName\": \"Client full name\", \"requiredItems\": \"List of required items (HTML format)\", \"resubmitUrl\": \"Resubmit documents URL\", \"platformName\": \"Platform/company name\"}', 1, '2025-12-23 02:33:03', '2025-12-23 02:33:03'),
(11, '测试1密钥', '测试1模板', 'transaction', '测试1主题', '测试1', 'client', '11111', '{\"1\":\"2\"}', 1, '2025-12-30 12:36:39', '2025-12-30 12:36:39');

