CREATE TABLE `emailVerificationSettings` (
  `id` int(11) UNSIGNED NOT NULL,
  `isRequired` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Require email verification for new accounts',
  `emailSubject` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Verify Your BDX Account',
  `emailTemplate` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Email template with placeholders like {user_name}, {verification_link}',
  `verificationLinkExpiryHours` int(11) NOT NULL DEFAULT '24',
  `allowResend` tinyint(1) NOT NULL DEFAULT '1',
  `resendCooldownMinutes` int(11) NOT NULL DEFAULT '5' COMMENT 'Minutes before user can request another email',
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Email verification configuration';

--
-- 插入之前先把表清空（truncate） `emailVerificationSettings`
--

TRUNCATE TABLE `emailVerificationSettings`;
--
-- 转存表中的数据 `emailVerificationSettings`
--

INSERT INTO `emailVerificationSettings` (`id`, `isRequired`, `emailSubject`, `emailTemplate`, `verificationLinkExpiryHours`, `allowResend`, `resendCooldownMinutes`, `updatedAt`) VALUES
(1, 0, 'Verify Your BDX Account', 'Dear {user_name},\n\nThank you for registering with BDX! To complete your registration and start trading, please verify your email address by clicking the link below:\n\n{verification_link}\n\nThis link will expire in 24 hours.\n\nIf you did not create this account, please ignore this email.\n\nBest regards,\nThe BDX Team', 24, 1, 5, '2025-12-01 01:59:05');

