--
-- 表的结构 `email_otp_verifications`
--

CREATE TABLE `email_otp_verifications` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` int(11) UNSIGNED NOT NULL COMMENT 'User ID (admin or client)',
  `user_type` enum('admin','client') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'User type: admin or client',
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Target email address to verify',
  `otp_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Hashed OTP code for security',
  `expires_at` datetime NOT NULL COMMENT 'Expiration time (10 minutes from creation)',
  `is_verified` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Whether OTP has been verified',
  `verified_at` datetime DEFAULT NULL COMMENT 'When OTP was verified',
  `attempts` int(11) NOT NULL DEFAULT '0' COMMENT 'Number of verification attempts',
  `max_attempts` int(11) NOT NULL DEFAULT '5' COMMENT 'Maximum allowed attempts',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IP address when OTP was requested',
  `user_agent` text COLLATE utf8mb4_unicode_ci COMMENT 'User agent when OTP was requested',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Email OTP verification codes for admin and client users';

--
-- 插入之前先把表清空（truncate） `email_otp_verifications`
--

TRUNCATE TABLE `email_otp_verifications`;
