--
-- 表的结构 `ibApplicationCustomRuleAdditionalRules`
--

CREATE TABLE `ibApplicationCustomRuleAdditionalRules` (
  `id` int(11) UNSIGNED NOT NULL,
  `customRuleId` int(11) UNSIGNED NOT NULL COMMENT 'Reference to ibApplicationCustomRules.id',
  `productType` enum('security','symbol','all') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'security',
  `productName` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Product name or NULL for all',
  `ruleType` enum('bonus_commission','volume_tiers','volume_multiplier','performance_bonus','cash_rebate') COLLATE utf8mb4_unicode_ci NOT NULL,
