INSERT INTO `ibDocumentTemplates` (`id`, `documentTitle`, `documentContent`, `iconClass`, `iconGradient`, `isRequired`, `displayOrder`, `wordCount`, `characterCount`, `estimatedReadTime`, `version`, `isActive`, `createdAt`, `updatedAt`, `createdBy`, `updatedBy`) VALUES
(1, 'IB Partnership Agreement', '<h3>IB Partnership Agreement</h3><p>This agreement is entered between BDX Trading Platform (\"Company\") and the Introducing Broker (\"IB\").</p><h4>1. Appointment</h4><p>The Company appoints the IB as an independent introducing broker to refer potential clients to the Company\'s trading platform.</p><h4>2. Commission Structure</h4><ul><li>Commissions are calculated based on referred client trading volume</li><li>Payment frequency: Monthly, within 5 business days</li><li>Minimum payout threshold: $100 USD</li></ul><h4>3. IB Responsibilities</h4><ul><li>Maintain professional conduct and ethical business practices</li><li>Comply with all applicable laws and regulations</li><li>Provide accurate information to referred clients</li></ul>', 'fas fa-handshake', 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', 1, 1, 250, 850, 2, '1.0', 1, '2025-11-20 06:50:28', '2025-11-20 06:50:28', NULL, NULL),
(2, 'Compliance & AML Declaration', '<h3>Compliance & Anti-Money Laundering Declaration</h3><p>As an Introducing Broker, I hereby declare and acknowledge:</p><ol><li>I will comply with all applicable Anti-Money Laundering (AML) and Counter-Terrorist Financing (CTF) regulations</li><li>I will not knowingly refer clients involved in illegal activities or from sanctioned countries</li><li>I will conduct appropriate due diligence on all referred clients</li><li>I will immediately report any suspicious activities to the Company</li><li>I understand that violation of compliance regulations may result in immediate termination of this agreement</li></ol>', 'fas fa-shield-alt', 'linear-gradient(135deg, #48bb78 0%, #38a169 100%)', 1, 2, 180, 720, 2, '1.0', 1, '2025-11-20 06:50:28', '2025-11-20 06:50:28', NULL, NULL),
(3, 'Commission Payment Terms', '<h3>Commission Payment Terms & Conditions</h3><h4>Payment Schedule</h4><ul><li><strong>Payment Frequency:</strong> Monthly, on the 5th business day of each month</li><li><strong>Minimum Payout:</strong> $100 USD (commissions below threshold roll over to next month)</li><li><strong>Payment Method:</strong> Bank transfer or other agreed method</li></ul><h4>Commission Calculation</h4><p>Commissions are calculated based on the selected commission plan and referred client trading activity during the commission period.</p><h4>Payment Currency</h4><p>All payments will be made in USD unless otherwise agreed in writing. Currency conversion fees may apply for non-USD payments.</p><h4>Tax Responsibilities</h4><p>The IB is responsible for all applicable taxes on commission payments. The Company may be required to withhold taxes as per local regulations.</p>', 'fas fa-dollar-sign', 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)', 1, 3, 220, 980, 3, '1.0', 1, '2025-11-20 06:50:28', '2025-11-20 06:50:28', NULL, NULL),
(4, 'Data Protection & Confidentiality Agreement', '<h3>Data Protection & Confidentiality</h3><h4>Confidential Information</h4><p>The IB acknowledges that during the course of this partnership, they may have access to confidential information including but not limited to:</p><ul><li>Client data and personal information</li><li>Commission structures and business strategies</li><li>Proprietary trading platform features</li><li>Marketing materials and business processes</li></ul><h4>Obligations</h4><ol><li>The IB must keep all confidential information strictly confidential</li><li>Confidential information may only be used for the purpose of this partnership</li><li>The IB must comply with GDPR and applicable data protection laws</li><li>Upon termination, all confidential information must be returned or destroyed</li></ol><h4>Data Processing</h4><p>The IB acts as a data processor and must ensure all client data is handled securely and in compliance with applicable regulations.</p>', 'fas fa-lock', 'linear-gradient(135deg, #3b82f6 0%, #1e40af 100%)', 1, 4, 280, 1100, 4, '1.0', 1, '2025-11-20 06:50:28', '2025-11-20 06:50:28', NULL, NULL);

