--
-- 表的结构 `kycEmailNotificationTemplates`
--

CREATE TABLE `kycEmailNotificationTemplates` (
  `id` int(11) UNSIGNED NOT NULL,
  `templateKey` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Unique identifier for template',
  `templateName` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Human-readable template name',
  `emailSubject` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Email subject line',
  `emailBody` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Email body content (supports HTML)',
  `emailType` enum('submission','approval','rejection','under_review','reminder','expiry','resubmit') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of email notification',
  `triggerEvent` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Event that triggers this email',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `sendDelay` int(11) DEFAULT '0' COMMENT 'Delay in minutes before sending (0 = immediate)',
  `ccEmails` text COLLATE utf8mb4_unicode_ci COMMENT 'Additional CC email addresses (JSON array)',
  `attachmentRequired` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Should include attachments',
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updatedBy` bigint(20) UNSIGNED DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='KYC Email Notification Templates';

--
-- 插入之前先把表清空（truncate） `kycEmailNotificationTemplates`
--

TRUNCATE TABLE `kycEmailNotificationTemplates`;
--
-- 转存表中的数据 `kycEmailNotificationTemplates`
--

INSERT INTO `kycEmailNotificationTemplates` (`id`, `templateKey`, `templateName`, `emailSubject`, `emailBody`, `emailType`, `triggerEvent`, `isActive`, `sendDelay`, `ccEmails`, `attachmentRequired`, `createdAt`, `updatedAt`, `updatedBy`) VALUES
(1, 'kyc_submission_confirmation', 'KYC Submission Confirmation', 'Your KYC Verification Has Been Submitted', '<p>Dear {{clientName}},</p><p>Thank you for submitting your KYC verification documents. We have received your application and our compliance team will review it shortly.</p><p><strong>What happens next?</strong></p><ul><li>Our team will verify your documents within 1-2 business days</li><li>You will receive an email notification once the review is complete</li><li>You can track your verification status in your dashboard</li></ul><p>If you have any questions, please don\'t hesitate to contact our support team.</p><p>Best regards,<br>Utrada CRM Team</p>', 'submission', 'kyc_submitted', 1, 0, NULL, 0, '2025-10-23 06:12:12', '2025-10-23 06:12:12', NULL),
(2, 'kyc_approval_notification', 'KYC Approval Notification', 'Your KYC Verification Has Been Approved!', '<p>Dear {{clientName}},</p><p>Great news! Your KYC verification has been approved.</p><p><strong>What this means for you:</strong></p><ul><li>Full access to all trading features</li><li>Higher transaction limits</li><li>Priority customer support</li><li>Access to advanced trading tools</li></ul><p>You can now start trading with complete confidence.</p><p><a href=\"{{dashboardUrl}}\">Go to Dashboard</a></p><p>Best regards,<br>Utrada CRM Team</p>', 'approval', 'kyc_approved', 1, 0, NULL, 0, '2025-10-23 06:12:12', '2025-10-23 06:12:12', NULL),
(3, 'kyc_rejection_notification', 'KYC Rejection Notification', 'Action Required: KYC Verification Issue', '<p>Dear {{clientName}},</p><p>We regret to inform you that we were unable to approve your KYC verification at this time.</p><p><strong>Reason for rejection:</strong></p><p>{{rejectionReason}}</p><p><strong>Next steps:</strong></p><ul><li>Review the feedback provided</li><li>Prepare the required documents</li><li>Resubmit your KYC application</li></ul><p><a href=\"{{resubmitUrl}}\">Resubmit Documents</a></p><p>If you need assistance, our support team is here to help.</p><p>Best regards,<br>Utrada CRM Team</p>', 'rejection', 'kyc_rejected', 1, 0, NULL, 0, '2025-10-23 06:12:12', '2025-10-23 06:12:12', NULL),
(4, 'kyc_under_review_notification', 'KYC Under Review', 'Your KYC Verification Is Under Review', '<p>Dear {{clientName}},</p><p>Your KYC documents are currently being reviewed by our compliance team.</p><p><strong>Review timeline:</strong></p><ul><li>Standard review: 1-2 business days</li><li>Complex cases: up to 5 business days</li><li>You will be notified as soon as the review is complete</li></ul><p>You can track your verification status in your dashboard.</p><p><a href=\"{{statusUrl}}\">Check Status</a></p><p>Thank you for your patience.</p><p>Best regards,<br>Utrada CRM Team</p>', 'under_review', 'kyc_under_review', 1, 60, NULL, 0, '2025-10-23 06:12:12', '2025-10-23 06:12:12', NULL),
(5, 'kyc_expiry_reminder', 'KYC Expiry Reminder', 'Your KYC Verification Will Expire Soon', '<p>Dear {{clientName}},</p><p>This is a friendly reminder that your KYC verification will expire on <strong>{{expiryDate}}</strong>.</p><p><strong>To maintain uninterrupted access:</strong></p><ul><li>Update your documents before the expiry date</li><li>Ensure all information is current and accurate</li><li>Submit updated proof of address if required</li></ul><p><a href=\"{{updateUrl}}\">Update Documents</a></p><p>Best regards,<br>Utrada CRM Team</p>', 'expiry', 'kyc_expiring_soon', 1, 0, NULL, 0, '2025-10-23 06:12:12', '2025-10-23 06:12:12', NULL),
(6, 'kyc_resubmit_request', 'KYC Resubmission Required', 'Additional Information Required for KYC Verification', '<p>Dear {{clientName}},</p><p>We need additional information to complete your KYC verification.</p><p><strong>Required items:</strong></p><p>{{requiredItems}}</p><p><strong>Please note:</strong></p><ul><li>Submit the requested documents within 7 days</li><li>Ensure all documents are clear and legible</li><li>Documents must be recent and valid</li></ul><p><a href=\"{{resubmitUrl}}\">Submit Documents</a></p><p>If you have questions, please contact our support team.</p><p>Best regards,<br>Utrada CRM Team</p>', 'resubmit', 'kyc_resubmit_required', 1, 0, NULL, 0, '2025-10-23 06:12:12', '2025-10-23 06:12:12', NULL);

