--
-- 表的结构 `kycNoticeSettings`
--

CREATE TABLE `kycNoticeSettings` (
  `id` int(11) UNSIGNED NOT NULL,
  `settingKey` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Unique identifier for setting type',
  `isEnabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Enable/disable this notice display',
  `noticeTitle` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Complete Your KYC Verification' COMMENT 'Main heading on KYC notice card',
  `noticeSubtitle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'Verify your identity to unlock full trading capabilities' COMMENT 'Secondary text below title',
  `noticeDescription` text COLLATE utf8mb4_unicode_ci COMMENT 'Main content text explaining KYC requirement',
  `requirementsTitle` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Required Documents' COMMENT 'Heading for required documents section',
  `verificationTimeNotice` text COLLATE utf8mb4_unicode_ci COMMENT 'Information about expected verification processing time',
  `primaryButtonText` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Start Verification Now' COMMENT 'Text for main action button',
  `primaryButtonAction` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '/client/kyc-verification' COMMENT 'URL or action for primary button',
  `secondaryButtonText` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Learn More' COMMENT 'Text for secondary action button',
  `secondaryButtonAction` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '/client/kyc-info' COMMENT 'URL or action for secondary button',
  `displayPosition` enum('top','center','bottom') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'top' COMMENT 'Position on dashboard',
  `displayPriority` int(11) NOT NULL DEFAULT '1' COMMENT 'Display priority (1=highest)',
  `isDismissible` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Can user dismiss the notice',
  `showIcon` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Show icon on notice card',
  `iconClass` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'fas fa-id-card' COMMENT 'Font Awesome icon class',
  `backgroundColor` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '#eef2ff' COMMENT 'Card background color',
  `borderColor` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '#667eea' COMMENT 'Card border color',
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updatedBy` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Admin user ID who last updated'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='KYC Notice Display Settings';

