  `reviewNotes` text COLLATE utf8mb4_unicode_ci COMMENT '审核备注',
  `approvedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '批准时间',
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='KYC Section级别批准记录（可选功能）';

