CREATE TABLE `kycSettingsChangeLog` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `settingType` enum('notice_settings','status_messages','requirements','email_templates') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of setting changed',
  `settingId` int(11) UNSIGNED NOT NULL COMMENT 'ID of the specific setting changed',
  `fieldName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of field that was changed',
