--
-- 表的结构 `kycStatusMessageTemplates`
--

CREATE TABLE `kycStatusMessageTemplates` (
  `id` int(11) UNSIGNED NOT NULL,
  `statusType` enum('draft','pending','under_review','approved','rejected','incomplete','expired','resubmit_required','pending_documents') COLLATE utf8mb4_unicode_ci NOT NULL,
  `messageTitle` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Status message title',
  `messageContent` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Detailed status message',
  `messageType` enum('info','success','warning','error') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'info' COMMENT 'Message display type',
  `showActionButton` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Show action button',
  `actionButtonText` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Action button text',
  `actionButtonUrl` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Action button URL',
  `iconClass` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'fas fa-info-circle' COMMENT 'Font Awesome icon class',
  `titleIcon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'fas fa-info-circle' COMMENT 'Title icon class',
  `badgeText` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Status badge text',
  `badgeClass` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'info' COMMENT 'Status badge CSS class',
  `isActive` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Is this template active',
  `displayOrder` int(11) NOT NULL DEFAULT '0' COMMENT 'Display order',
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updatedBy` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'Admin user ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='KYC Status Message Templates';

