(1, 'pending', 'KYC Verification Pending', 'Your KYC verification is pending. Please complete the required steps to activate your account.', 'warning', 1, 'Complete Verification', '/client/kyc-verification', 'fas fa-clock', 'fas fa-clock', 'Pending Review', 'info', 1, 1, '2025-10-23 06:12:12', '2025-10-30 14:55:37', NULL),
(2, 'under_review', 'KYC Under Review', 'Your documents are currently being reviewed by our compliance team. This typically takes 1-2 business days. We will notify you once the review is complete.', 'info', 0, NULL, NULL, 'fas fa-hourglass-half', 'fas fa-search', 'Under Review', 'info', 1, 2, '2025-10-23 06:12:12', '2025-10-30 14:55:37', NULL),
(3, 'approved', 'KYC Verification Approved', 'Congratulations! Your KYC verification has been approved. You now have full access to all trading features.', 'success', 1, 'Open New Account', '/client/account/new', 'fas fa-check-circle', 'fas fa-check-circle', 'Approved', 'success', 1, 3, '2025-10-23 06:12:12', '2025-10-30 14:55:37', NULL),
(4, 'rejected', 'KYC Verification Rejected', 'Unfortunately, your KYC verification has been rejected. Please review the reasons and resubmit your documents.', 'error', 1, 'View Details', '/client/kyc-status', 'fas fa-times-circle', 'fas fa-times-circle', 'Rejected', 'error', 1, 4, '2025-10-23 06:12:12', '2025-10-30 14:55:37', NULL),
(5, 'incomplete', 'KYC Verification Incomplete', 'Your KYC submission is incomplete. Please provide all required documents and information to proceed.', 'warning', 1, 'Complete Application', '/client/kyc-verification', 'fas fa-exclamation-triangle', 'fas fa-hourglass-half', 'In Progress', 'incomplete', 1, 5, '2025-10-23 06:12:12', '2025-10-30 15:05:06', NULL),
(6, 'expired', 'KYC Verification Expired', 'Your KYC verification has expired. Please submit updated documents to maintain your account status.', 'error', 1, 'Update Documents', '/client/kyc-verification', 'fas fa-calendar-times', 'fas fa-hourglass-half', 'Expired', 'warning', 1, 6, '2025-10-23 06:12:12', '2025-10-30 14:55:37', NULL),
(7, 'resubmit_required', 'Resubmission Required', 'Additional documents or information are required. Please review the feedback and resubmit your KYC application.', 'warning', 1, 'Resubmit Documents', '/client/kyc-verification', 'fas fa-redo', 'fas fa-hourglass-half', 'Resubmit Required', 'warning', 1, 7, '2025-10-23 06:12:12', '2025-10-30 14:55:37', NULL),
(10, 'pending_documents', 'KYC Verification Pending - Need More Documents', 'We need additional documents to complete your KYC verification.', 'warning', 1, 'Upload Documents', '/client/kyc-verification', 'fas fa-upload', 'fas fa-file-upload', 'Documents Required', 'warning', 1, 8, '2025-10-29 15:34:04', '2025-10-30 14:55:37', NULL);

