--
-- 表的结构 `languagePacks`
--

CREATE TABLE `languagePacks` (
  `id` int(11) UNSIGNED NOT NULL,
  `languageCode` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ISO language code (en, zh, th, vi, ja, etc.)',
  `languageName` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Display name of language',
  `flagEmoji` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Flag emoji or icon',
  `translations` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JSON object containing all translations',
  `isEnabled` tinyint(1) NOT NULL DEFAULT '1',
  `isDefault` tinyint(1) NOT NULL DEFAULT '0',
  `isBuiltin` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Built-in language cannot be deleted',
  `lastUpdated` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Language packs for client portal';

